// ZGC on 21:   -XX:+UseZGC -XX:+ZGenerational
// ZGC on 25:   -XX:+UseZGC
// Epsilon:     -XX:+UnlockExperimentalVMOptions -XX:+UseEpsilonGC   (unlock first)
// 2 CPUs, 1.5 GiB = 1,536 MB < 1,792 MB: not server-class, so Serial (G1 on JDK 27)
static Collector defaultCollector(int jdk, int cpus, long memoryMb) {
    if (jdk >= 27) return Collector.G1;
    return cpus >= 2 && memoryMb >= 1_792 ? Collector.G1 : Collector.SERIAL;
}

